CREATE OR REPLACE FUNCTION public.metrics_inventory(_scope jsonb DEFAULT '{}') RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ WITH u AS(SELECT * FROM public.metrics_unit_scope u WHERE public.metrics_scope_match(u,_scope)), totals AS(SELECT count(*) AS total,count(*) FILTER(WHERE publish_state='published') AS published,count(*) FILTER(WHERE publish_state='draft') AS draft,count(*) FILTER(WHERE publish_state NOT IN('draft','published')) AS unpublished,count(*) FILTER(WHERE publish_state='published' AND leasing_status='leased') AS leased,count(*) FILTER(WHERE leasing_status='available') AS available,count(*) FILTER(WHERE publish_state='published' AND leasing_status IN('leased','on_hold','pending_contract')) AS occupied FROM u), grouped AS(SELECT 'building' AS dimension,building_number::text AS key,'مبنى '||building_number::text AS label,publish_state,coalesce(leasing_status::text,'review') AS status,count(*) AS count FROM u GROUP BY building_number,publish_state,leasing_status UNION ALL SELECT 'activity',coalesce(activity_id::text,'unassigned'),coalesce(activity_name,'نشاط غير محدد'),publish_state,coalesce(leasing_status::text,'review'),count(*) FROM u GROUP BY activity_id,activity_name,publish_state,leasing_status) SELECT to_jsonb(t)||jsonb_build_object('leased_rate',public.metrics_ratio(t.leased,t.published),'occupancy_rate',public.metrics_ratio(t.occupied,t.published),'groups',coalesce((SELECT jsonb_agg(to_jsonb(g) ORDER BY dimension,label,publish_state,status) FROM grouped g),'[]')) FROM totals t $$;
CREATE OR REPLACE FUNCTION public.metrics_regression_tests() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s jsonb;BEGIN IF public.metrics_is_overdue(date '2026-11-02',date '2026-11-05',3) THEN RAISE EXCEPTION '3-day boundary failed';END IF;IF NOT public.metrics_is_overdue(date '2026-11-01',date '2026-11-05',3) THEN RAISE EXCEPTION 'After 3-day boundary failed';END IF;IF public.metrics_ratio(1,0) IS NOT NULL THEN RAISE EXCEPTION 'Zero denominator failed';END IF;IF public.metrics_ratio(37,708)<>5.23 THEN RAISE EXCEPTION 'Leasing ratio failed';END IF;IF public.metrics_ratio(40,708)<>5.65 THEN RAISE EXCEPTION 'Occupancy ratio failed';END IF;IF public.metrics_ratio(60,115)<>52.17 THEN RAISE EXCEPTION 'Allocated-period ratio failed';END IF;s:=public._metrics_snapshot('{}','service');IF (s->'inventory'->>'total')::integer<>(SELECT count(*) FROM public.units WHERE NOT is_test) THEN RAISE EXCEPTION 'Test-unit exclusion failed';END IF;IF has_function_privilege('authenticated','public.metrics_service_snapshot(jsonb)','EXECUTE') THEN RAISE EXCEPTION 'Service boundary failed';END IF;RETURN jsonb_build_object('passed',8,'as_of',now());END $$;
REVOKE ALL ON FUNCTION public.metrics_regression_tests() FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.metrics_regression_tests() TO service_role;
SELECT to_regprocedure('public.metrics_regression_tests()') IS NOT NULL AS tests_ready;